package com.example.demo.accounting;
import org.junit.jupiter.api.Test;
import java.util.Map;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;
class PayrollBreakdownTest {
 @Test void reportsRecordedPfAndTdsWithoutRateAssumptions(){var result=PayrollBreakdown.parse("{\"pretax_deductions\":[{\"deduction_id\":1,\"amount\":1234.56,\"employer_contribution_amount\":987.65}],\"tax_deductions\":[{\"deduction_id\":2,\"amount\":4321.09}]}",Map.of(1L,"PF",2L,"TDS"),new BigDecimal("5555.65"));assertThat(result.pf()).isEqualByComparingTo("1234.56");assertThat(result.employerPf()).isEqualByComparingTo("987.65");assertThat(result.tds()).isEqualByComparingTo("4321.09");assertThat(result.classified()).isTrue();}
 @Test void unmappedDeductionIsFlagged(){var result=PayrollBreakdown.parse("{\"pretax_deductions\":[{\"deduction_id\":1,\"title\":\"PF\",\"amount\":2000}]}",Map.of(),new BigDecimal("2000"));assertThat(result.classified()).isFalse();assertThat(result.warnings()).anyMatch(w->w.contains("Classify"));}
 @Test void missingOrInvalidBreakdownNeedsReview(){assertThat(PayrollBreakdown.parse(null,Map.of(),new BigDecimal("3000")).classified()).isFalse();assertThat(PayrollBreakdown.parse("broken-json",Map.of(),new BigDecimal("3000")).classified()).isFalse();}
 @Test void withholdingMustBeExplicitlyClassified(){assertThat(PayrollBreakdown.parse("{\"federal_tax\":1000}",Map.of(),new BigDecimal("1000")).classified()).isFalse();var result=PayrollBreakdown.parse("{\"federal_tax\":1000}",Map.of(0L,"TDS"),new BigDecimal("1000"));assertThat(result.classified()).isTrue();assertThat(result.tds()).isEqualByComparingTo("1000");}
 @Test void totalsMustReconcile(){var result=PayrollBreakdown.parse("{\"loss_of_pay\":1000}",Map.of(),new BigDecimal("3000"));assertThat(result.classified()).isFalse();assertThat(result.warnings()).anyMatch(w->w.contains("differs"));}
 @Test void compensationAdjustmentsCannotSilentlyBecomeStatutoryDeductions(){var result=PayrollBreakdown.parse("{\"gross_pay_deductions\":[{\"deduction_id\":1,\"amount\":1000}]}",Map.of(1L,"PF"),BigDecimal.ZERO);assertThat(result.classified()).isFalse();}
 @Test void loanAndAbsenceAmountsRemainSeparate(){var result=PayrollBreakdown.parse("{\"loan_deductions\":[{\"amount\":1500}],\"loss_of_pay\":1000,\"attendance_deduction\":500}",Map.of(),new BigDecimal("3000"));assertThat(result.classified()).isTrue();assertThat(result.loans()).isEqualByComparingTo("1500");assertThat(result.lop()).isEqualByComparingTo("1000");}
 @Test void reportsIndiaEsiPtAndLwfWithoutRateAssumptions(){var result=PayrollBreakdown.parse("{\"pretax_deductions\":[{\"deduction_id\":1,\"amount\":150.00,\"employer_contribution_amount\":650.00},{\"deduction_id\":2,\"amount\":200.00,\"employer_contribution_amount\":0},{\"deduction_id\":3,\"amount\":25.00,\"employer_contribution_amount\":50.00}]}",Map.of(1L,"IN_ESI",2L,"IN_PT",3L,"IN_LWF"),new BigDecimal("375.00"));assertThat(result.classified()).isTrue();assertThat(result.indiaTaxes().get("esi")).isEqualByComparingTo("150.00");assertThat(result.indiaTaxes().get("employer_esi")).isEqualByComparingTo("650.00");assertThat(result.indiaTaxes().get("professional_tax")).isEqualByComparingTo("200.00");assertThat(result.indiaTaxes().get("lwf")).isEqualByComparingTo("25.00");assertThat(result.indiaTaxes().get("employer_lwf")).isEqualByComparingTo("50.00");}
}
